def by_category() -> dict[str, tuple[AuthCase, ...]]:
    out: dict[str, list[AuthCase]] = {c: [] for c in CATEGORIES}
    for case in CASES:
        out[case.category].append(case)
    return {k: tuple(v) for k, v in out.items()}
